11	#ifndef ATVOSS_EXPR_LINEARIZER_H
12	#define ATVOSS_EXPR_LINEARIZER_H
13	#include <cstddef>
14	
15	#include "expression/expr_template.h"
16	#include "utils/utility.h"
17	#include "expr_cast_eliminate.h"
18	
19	namespace Atvoss {
20	namespace Detail {
21	/**
22	 *
23	 * @tparam Expr TypeList
24	 * @tparam From 需要替换的类型
25	 * @tparam To 目标类型
26	 */
27	template <typename Expr, typename From, typename To>
28	struct ReplaceExpr;
29	
30	/**
31	 * 递归替换引擎
32	 * @tparam Expr TypeList
33	 * @tparam From 需要替换的类型
34	 * @tparam To 目标类型
35	 */
36	template <typename Expr, typename From, typename To>
37	struct ReplaceRecursive {
38	    using Type = Expr; // 默认不处理
39	};
40	
41	// 基本情况：完全匹配则替换
42	template <typename Expr, typename From, typename To>
43	struct ReplaceExpr {
44	    using Type = std::conditional_t<
45	        std::is_same_v<Expr, From>, To,
46	        // 否则递归下降
47	        typename ReplaceRecursive<Expr, From, To>::Type>;
48	};
49	
50	// 对 Param 不再递归
51	template <size_t N, typename T, auto Usage, size_t R, typename From, typename To>
52	struct ReplaceExpr<Atvoss::Param<N, T, Usage, R>, From, To> {
53	    using Type = Atvoss::Param<N, T, Usage, R>;
54	};
55	
56	// 二元操作符递归
57	template <template <typename, typename> class Op, typename LHS, typename RHS, typename From, typename To>
58	struct ReplaceRecursive<Op<LHS, RHS>, From, To> {
59	    using newLhs = typename ReplaceExpr<LHS, From, To>::Type;
60	    using newRhs = typename ReplaceExpr<RHS, From, To>::Type;
61	    using Type = Op<newLhs, newRhs>;
62	};
63	
64	// 一元操作符递归
65	template <template <typename> class Op, typename Inner, typename From, typename To>
66	struct ReplaceRecursive<Op<Inner>, From, To> {
67	    using newInner = typename ReplaceExpr<Inner, From, To>::Type;
68	    using Type = Op<newInner>;
69	};
70	
71	// 带非类型模板参数的操作符
72	template <template <auto, typename> class Op, auto N, typename Inner, typename From, typename To>
73	struct ReplaceRecursive<Op<N, Inner>, From, To> {
74	    using newInner = typename ReplaceExpr<Inner, From, To>::Type;
75	    using Type = Op<N, newInner>;
76	};
77	
78	// 匹配OpCast
79	template <template <auto, typename, typename> class Op, auto N, typename R, typename Inner, typename From, typename To>
80	struct ReplaceRecursive<Op<N, R, Inner>, From, To> {
81	    using newInner = typename ReplaceExpr<Inner, From, To>::Type;
82	    using Type = Op<N, R, newInner>;
83	};
84	
85	// ========================================================
86	// ExtractTypeListPostOrder: 后序遍历提取表达式列表
87	// ========================================================
88	template <typename Expr, typename = void>
89	struct ExtractTypeListPostOrder;
90	
91	// 终止：Param 不展开
92	template <size_t N, typename T, auto Usage, size_t R>
93	struct ExtractTypeListPostOrder<Atvoss::Param<N, T, Usage, R>> {
94	    using Type = Atvoss::Util::TypeList<>;
95	};
96	
97	// 终止：LocalVar 不展开
98	template <size_t N, typename T, typename U>
99	struct ExtractTypeListPostOrder<Atvoss::LocalVar<N, T, U>> {
100	    using Type = Atvoss::Util::TypeList<>;
101	};
102	
103	template <template <typename, typename> class Op, typename LHS, typename RHS>
104	struct ExtractTypeListPostOrder<Op<LHS, RHS>, std::enable_if_t<IsBinaryOp_v<Op<LHS, RHS>>>> {
105	    using lhsList = typename ExtractTypeListPostOrder<LHS>::Type;
106	    using rhsList = typename ExtractTypeListPostOrder<RHS>::Type;
107	    using concatList = typename Atvoss::Util::Concatenate<
108	        typename std::conditional_t<
109	            Atvoss::Util::IsSpecializationOf_v<Atvoss::OpAssign, Op<LHS, RHS>>,
110	            typename Atvoss::Util::Concatenate<rhsList, lhsList>, // 赋值操作符：先右后左
111	            typename Atvoss::Util::Concatenate<lhsList, rhsList>  // 先左后右
112	            >::Type,
113	        std::conditional_t<
114	            Atvoss::Util::IsSpecializationOf_v<Atvoss::OpAndThen, Op<LHS, RHS>>, Atvoss::Util::TypeList<>,
115	            Atvoss::Util::TypeList<Op<LHS, RHS>>>>::Type;
116	    using Type = concatList;
117	};
118	
119	// 一元操作符
120	template <template <typename> class Op, typename Expr>
121	struct ExtractTypeListPostOrder<Op<Expr>> {
122	    using innerList = typename ExtractTypeListPostOrder<Expr>::Type;
123	    using Type = typename Atvoss::Util::Concatenate<innerList, Atvoss::Util::TypeList<Op<Expr>>>::Type;
124	};
125	
126	template <template <auto, typename> class Op, auto Pattern, typename Expr>
127	struct ExtractTypeListPostOrder<Op<Pattern, Expr>> {
128	    using innerList = typename ExtractTypeListPostOrder<Expr>::Type;
129	    using Type = typename Atvoss::Util::Concatenate<innerList, Atvoss::Util::TypeList<Op<Pattern, Expr>>>::Type;
130	};
131	
132	template <template <auto, typename, typename> class Op, auto Pattern, typename R, typename Expr>
133	struct ExtractTypeListPostOrder<Op<Pattern, R, Expr>> {
134	    using innerList = typename ExtractTypeListPostOrder<Expr>::Type;
135	    using Type = typename Atvoss::Util::Concatenate<innerList, Atvoss::Util::TypeList<Op<Pattern, R, Expr>>>::Type;
136	};
137	
138	using Atvoss::Util::TypeList;
139	
140	// LocalVar的number与其右边的表达式的映射关系
141	template <size_t ID, typename Expr>
142	struct VarDef {};
143	
144	// 查找变量定义
145	template <size_t ID, typename DefList>
146	struct FindVarDef;
147	
148	template <size_t ID>
149	struct FindVarDef<ID, TypeList<>> {
150	    using Type = void;
151	};
152	
153	template <size_t ID, typename Expr, typename... Rest>
154	struct FindVarDef<ID, TypeList<VarDef<ID, Expr>, Rest...>> {
155	    using Type = Expr;
156	};
157	
158	template <size_t ID, size_t OtherID, typename Expr, typename... Rest>
159	struct FindVarDef<ID, TypeList<VarDef<OtherID, Expr>, Rest...>> {
160	    using Type = typename FindVarDef<ID, TypeList<Rest...>>::Type;
161	};
162	
163	// 检查 LocalVar 是否会被后面的 Param 引用
164	template <size_t ID, typename StmtList>
165	struct IsLocalVarReferencedByParam;
166	
167	template <size_t ID>
168	struct IsLocalVarReferencedByParam<ID, TypeList<>> {
169	    static constexpr bool value = false;
170	};
171	
172	template <size_t ID, typename NextStmt, typename... OtherStmts>
173	struct IsLocalVarReferencedByParam<ID, TypeList<NextStmt, OtherStmts...>> {
174	    // 检查 NextStmt 是否是 OpAssign<Param<...>, LocalVar<ID, ...>>
175	    template <typename Stmt>
176	    struct CheckStmt;
177	
178	    template <size_t PID, typename PT, ParamUsage PU, size_t LID, typename LT, typename LSrc>
179	    struct CheckStmt<OpAssign<Param<PID, PT, PU>, LocalVar<LID, LT, LSrc>>> {
180	        static constexpr bool value = (LID == ID);
181	    };
182	
183	    template <typename Other>
184	    struct CheckStmt {
185	        static constexpr bool value = false;
186	    };
187	
188	    static constexpr bool current = CheckStmt<NextStmt>::value;
189	    static constexpr bool rest = IsLocalVarReferencedByParam<ID, TypeList<OtherStmts...>>::value;
190	    static constexpr bool value = current || rest;
191	};
192	
193	/**
194	 * 把无效的localVar简化掉，比如localVar1 = in1*in1, out = localVar1简化成 out = in1*in1.
195	 * @tparam TypeList 需要简化的表达式的初始列表
196	 * @tparam DefList VarDef的列表，存放的是LocalVar的number与其右边的表达式的映射关系
197	 * @tparam Result 化简后的结果
198	 */
199	template <typename TypeList, typename DefList = Atvoss::Util::TypeList<>, typename Result = Atvoss::Util::TypeList<>>
200	struct SimplifyImpl;
201	
202	// 递归终止条件：需要简化的列表为空
203	template <typename... Defs, typename... ResultTypes>
204	struct SimplifyImpl<TypeList<>, TypeList<Defs...>, TypeList<ResultTypes...>> {
205	    using result = TypeList<ResultTypes...>;
206	};
207	
208	// 递归处理
209	template <typename First, typename... Rest, typename... Defs, typename... ResultTypes>
210	struct SimplifyImpl<TypeList<First, Rest...>, TypeList<Defs...>, TypeList<ResultTypes...>> {
211	private:
212	    // 辅助：处理 LocalVar 定义语句
213	    template <size_t ID, typename T, typename Likes, typename Expr>
214	    struct ProcessLocalVarDef {
215	        // 检查这个 LocalVar 是否会被后面的 Param 引用
216	        static constexpr bool willBeReplaced = IsLocalVarReferencedByParam<ID, TypeList<Rest...>>::value;
217	
218	        using newDefs = TypeList<Defs..., VarDef<ID, Expr>>;
219	
220	        // 如果会被替换，就不保留这个语句
221	        using Type = std::conditional_t<
222	            willBeReplaced, std::integral_constant<int, 0>, // 标记为删除
223	            OpAssign<LocalVar<ID, T, Likes>, Expr>          // 保留
224	            >;
225	    };
226	
227	    // 辅助：处理 Param 赋值给 LocalVar
228	    template <size_t PID, typename PT, ParamUsage PU, size_t LID, typename LT, typename Likes, typename RestList>
229	    struct ProcessParamAssign {
230	        // 查找 LocalVar 的定义
231	        using found = FindVarDef<LID, TypeList<Defs...>>;
232	        using newDefs = TypeList<Defs...>;
233	
234	        using Type = std::conditional_t<
235	            !std::is_same_v<typename found::Type, void>,
236	            OpAssign<Param<PID, PT, PU>, typename found::Type>,    // 替换为表达式
237	            OpAssign<Param<PID, PT, PU>, LocalVar<LID, LT, Likes>> // 保持原样
238	            >;
239	
240	        template <typename T>
241	        using ReplaceLocalVar2Param = ReplaceExpr<T, LocalVar<LID, LT, Likes>, Param<PID, PT, PU>>;
242	        using restList = Util::Map_t<ReplaceLocalVar2Param, RestList>;
243	    };
244	
245	    // 辅助：处理其他语句
246	    template <typename Stmt>
247	    struct ProcessOther {
248	        using newDefs = TypeList<Defs...>;
249	        using Type = Stmt;
250	    };
251	
252	    // 分发处理逻辑
253	    template <typename Stmt, typename RestList>
254	    struct ProcessStmt;
255	
256	    // 匹配 OpAssign<LocalVar<...>, Expr>
257	    template <size_t ID, typename T, typename Likes, typename Expr, typename RestList>
258	    struct ProcessStmt<OpAssign<LocalVar<ID, T, Likes>, Expr>, RestList> {
259	        using processor = ProcessLocalVarDef<ID, T, Likes, Expr>;
260	        using newDefs = typename processor::newDefs;
261	        using resultType = typename processor::Type;
262	        using restList = RestList;
263	    };
264	
265	    // 匹配 OpAssign<Param<...>, LocalVar<...>>
266	    template <size_t PID, typename PT, ParamUsage PU, size_t LID, typename LT, typename Likes, typename RestList>
267	    struct ProcessStmt<OpAssign<Param<PID, PT, PU>, LocalVar<LID, LT, Likes>>, RestList> {
268	        using processor = ProcessParamAssign<PID, PT, PU, LID, LT, Likes, RestList>;
269	        using newDefs = typename processor::newDefs;
270	        using resultType = typename processor::Type;
271	        using restList = typename processor::restList;
272	    };
273	
274	    // 匹配其他类型
275	    template <typename Stmt, typename RestList>
276	    struct ProcessStmt {
277	        using processor = ProcessOther<Stmt>;
278	        using newDefs = typename processor::newDefs;
279	        using resultType = typename processor::Type;
280	        using restList = RestList;
281	    };
282	
283	    // 处理当前语句
284	    using processor = ProcessStmt<First, TypeList<Rest...>>;
285	    using newDefs = typename processor::newDefs;
286	    using currentResult = typename processor::resultType;
287	
288	    // 判断是否需要将当前结果添加到最终列表中
289	    using nextResult = std::conditional_t<
290	        std::is_same_v<currentResult, std::integral_constant<int, 0>>,
291	        // 如果是删除标记，不添加
292	        TypeList<ResultTypes...>,
293	        // 否则添加
294	        TypeList<ResultTypes..., currentResult>>;
295	
296	    // 继续处理剩余部分
297	    using next = SimplifyImpl<typename processor::restList, newDefs, nextResult>;
298	
299	public:
300	    using result = typename next::result;
301	};
302	
303	// 将 [LocalVar1 = in1 * ini1, out = LocalVar1] 化简成 out = in1 * in1
304	template <typename List>
305	struct Simplify {
306	    using Type = typename SimplifyImpl<List>::result;
307	};
308	
309	// ========================================================
310	// OptimizeWithLocalVars: 将中间结果缓存为 LocalVar
311	// ========================================================
312	template <typename ExprList, size_t LocalVarNumber, typename Processed>
313	struct OptimizeWithLocalVarsImpl;
314	
315	// 终止条件
316	template <size_t LocalVarNumber, typename Processed>
317	struct OptimizeWithLocalVarsImpl<Atvoss::Util::TypeList<>, LocalVarNumber, Processed> {
318	    using Type = Processed;
319	};
320	
321	// 主递归：处理第一个表达式
322	template <typename First, typename... Rest, size_t LocalVarNumber, typename Processed>
323	struct OptimizeWithLocalVarsImpl<Atvoss::Util::TypeList<First, Rest...>, LocalVarNumber, Processed> {
324	private:
325	    // 判断是否应该缓存
326	    static constexpr bool shouldCache = !Atvoss::IsParam_v<First>;
327	    static constexpr bool firstIsOpAssign = Atvoss::Util::IsSpecializationOf_v<Atvoss::OpAssign, First>;
328	    static constexpr auto NextLocalVarNumber = firstIsOpAssign ? LocalVarNumber : LocalVarNumber + 1;
329	
330	    // LocalVar 类型
331	    using localVarType = Atvoss::LocalVar<
332	        LocalVarNumber, typename First::RetType, Atvoss::Param<1ul, typename First::RetType, (Atvoss::ParamUsage)0>>;
333	
334	    // 构造赋值语句
335	    using assignmentType = std::conditional_t<firstIsOpAssign, First, Atvoss::OpAssign<localVarType, First>>;
336	
337	    template <typename Expr>
338	    using ReplaceOne = typename ReplaceExpr<Expr, First, localVarType>::Type;
339	    using updatedRest = Atvoss::Util::TypeList<ReplaceOne<Rest>...>;
340	
341	    // 下一步状态
342	    using nextProcessed = typename std::conditional_t<
343	        shouldCache, Atvoss::Util::Append<Processed, assignmentType>, Util::TypeWrapper<Processed>>::Type;
344	
345	    using nextState = std::conditional_t<
346	        shouldCache, OptimizeWithLocalVarsImpl<updatedRest, NextLocalVarNumber, nextProcessed>,
347	        OptimizeWithLocalVarsImpl<Atvoss::Util::TypeList<Rest...>, LocalVarNumber, nextProcessed>>;
348	
349	public:
350	    using Type = typename nextState::Type;
351	};
352	
353	// 主入口
354	template <typename ExprList>
355	struct OptimizeWithLocalVars : OptimizeWithLocalVarsImpl<ExprList, 1, Atvoss::Util::TypeList<>> {};
356	
357	template <typename ExprList, typename Processed>
358	struct OptimizeBindBuffExprImpl;
359	
360	// 终止条件
361	template <typename Processed>
362	struct OptimizeBindBuffExprImpl<Atvoss::Util::TypeList<>, Processed> {
363	    using Type = Processed;
364	};
365	
366	template <typename T>
367	struct SimplifyAssignOfOpParam {
368	    using Type = T;
369	};
370	
371	template <typename LHS, typename RHS>
372	struct SimplifyAssignOfOpParam<Atvoss::OpAssign<LHS, RHS>> {
373	    using Type = LHS;
374	};
375	
376	template <typename T>
377	struct SimplifyAssign;
378	
379	// 对 Param 不再递归
380	template <size_t N, typename T, auto Usage, size_t R>
381	struct SimplifyAssign<Atvoss::Param<N, T, Usage, R>> {
382	    using Type = Atvoss::Param<N, T, Usage, R>;
383	};
384	
385	template <typename LHS, typename RHS>
386	struct SimplifyAssign<Atvoss::OpAssign<LHS, RHS>> {
387	    using Type = Atvoss::OpAssign<LHS, typename SimplifyAssign<RHS>::Type>;
388	};
389	
390	// 二元操作符通用匹配
391	template <template <typename, typename> class Op, typename LHS, typename RHS>
392	struct SimplifyAssign<Op<LHS, RHS>> {
393	    using Type = Op<typename SimplifyAssignOfOpParam<LHS>::Type, typename SimplifyAssignOfOpParam<RHS>::Type>;
394	};
395	
396	// 一元操作符通用匹配
397	template <template <typename> class Op, typename Expr>
398	struct SimplifyAssign<Op<Expr>> {
399	    using Type = Op<typename SimplifyAssignOfOpParam<Expr>::Type>;
400	};
401	
402	// 匹配带非类型模板参数的一元操作符：Op<Pat, E>
403	template <template <auto, typename> class Op, auto N, typename Expr>
404	struct SimplifyAssign<Op<N, Expr>> {
405	    using Type = Op<N, typename SimplifyAssignOfOpParam<Expr>::Type>;
406	};
407	
408	// 匹配带非类型模板参数的一元操作符：Op<Pat, E>
409	template <auto N, typename R, typename Expr>
410	struct SimplifyAssign<Atvoss::OpCast<N, R, Expr>> {
411	    using Type = Atvoss::OpCast<N, R, typename SimplifyAssignOfOpParam<Expr>::Type>;
412	};
413	
414	// First为OpAssign直接跳过，对OpAssign的右边进行化简，
415	// 比如把OpAdd(LocalVar2, OpAssign(LocalVar1, OpMul(in1*in1)))
416	// 化简成OpAdd(LocalVar2, LocalVar1)
417	template <typename First, typename... Rest, typename Processed>
418	struct OptimizeBindBuffExprImpl<Atvoss::Util::TypeList<First, Rest...>, Processed> {
419	private:
420	    // 判断是否应该缓存
421	    static constexpr bool shouldCache = !Atvoss::IsParam_v<First>;
422	
423	    // LocalVar 类型
424	    using localVarType = First;
425	
426	    // 化简OpAssign：把OpAssign(LocalVar3, OpAdd(LocalVar2, OpAssign(LocalVar1, OpMul(in1*in1))))
427	    // 化简成：OpAssign(LocalVar3, OpAdd(LocalVar2, LocalVar1))
428	    using assignSimplified = std::conditional_t<
429	        Atvoss::Util::IsSpecializationOf_v<Atvoss::OpAssign, First>, TypeList<typename SimplifyAssign<First>::Type>,
430	        TypeList<>>;
431	
432	    // 下一步状态
433	    using nextProcessed = Atvoss::Util::Concatenate_t<Processed, assignSimplified>;
434	
435	    using nextState = OptimizeBindBuffExprImpl<Atvoss::Util::TypeList<Rest...>, nextProcessed>;
436	
437	public:
438	    using Type = typename nextState::Type;
439	};
440	
441	// 主入口
442	template <typename ExprList>
443	struct OptimizeBindBuffExpr : OptimizeBindBuffExprImpl<ExprList, Atvoss::Util::TypeList<>> {};
444	
445	template <typename Expr>
446	struct ExprLinearizer {
447	    using postOrderList = Atvoss::Util::Unique_t<typename ExtractTypeListPostOrder<Expr>::Type>;
448	    using removeRedundantCastExprList =
449	        decltype(Atvoss::Graph::RemoveRedundantCast<typename std::conditional_t<
450	                     Util::Size<typename LocalVars<Expr>::Type>::value == 0, OptimizeWithLocalVars<postOrderList>,
451	                     OptimizeBindBuffExpr<postOrderList>>::Type>());
452	    using optimizedList = typename Simplify<removeRedundantCastExprList>::Type;
453	};
454	} // namespace Detail
455	
456	template <typename Expr>
457	__host_aicore__ constexpr auto ToLinearizerExpr(Expr expr)
458	{
459	    return typename ToOpAndThenExpr<typename Detail::ExprLinearizer<typename Expr::Type>::optimizedList>::Type();
460	}
461	
462	} // namespace Atvoss
463	
464	#endif // ATVOSS_EXPR_LINEARIZER_H

