47	template <typename LocalVarList, typename TargetOp>
48	constexpr bool FindLocalVarIndex = false;
49	
50	template <typename TargetOp>
51	constexpr bool FindLocalVarIndex<TypeList<>, TargetOp> = false;
52	
53	template <typename Head, typename... Tail, typename TargetOp>
54	constexpr bool FindLocalVarIndex<TypeList<Head, Tail...>, TargetOp> =
55	    std::is_same_v<typename Head::Like, TargetOp> ? true : FindLocalVarIndex<TypeList<Tail...>, TargetOp>;
56	
57	template <typename LocalVarList, typename TargetOp>
58	constexpr size_t GetLocalVarIndex = 0;
59	
60	template <typename TargetOp>
61	constexpr size_t GetLocalVarIndex<TypeList<>, TargetOp> = 0;
62	
63	template <typename Head, typename... Tail, typename TargetOp>
64	constexpr size_t GetLocalVarIndex<TypeList<Head, Tail...>, TargetOp> =
65	    std::is_same_v<typename Head::Like, TargetOp> ? Head::number : GetLocalVarIndex<TypeList<Tail...>, TargetOp>;
66	/*--------------------------------------------------------------------------------------------------------------------*/
67	template <typename Operand, size_t Idx, typename M>
68	constexpr auto CreateLocalVar(M map)
69	{
70	    if constexpr (IsParam_v<Operand>) {
71	        return std::make_pair(map, Operand{});
72	    } else if constexpr (FindLocalVarIndex<M, Operand>) {
73	        constexpr size_t idx = GetLocalVarIndex<M, Operand>;
74	        using LocalVarType = LocalVar<idx, float, ParaConst>;
75	        return std::make_pair(map, LocalVarType{});
76	    } else {
77	        using NewLocalVar = LocalVar<Idx, float, Operand>;
78	        using MergedMap = Append_t<M, NewLocalVar>;
79	        using LocalVarType = LocalVar<Idx, float, ParaConst>;
80	        return std::make_pair(MergedMap{}, LocalVarType{});
81	    }
82	}
83	
84	template <typename Lhs, typename Rhs, typename... Operands>
85	using MakeAssignOp = OpAssign<Lhs, typename ReplaceOp<Rhs, Operands...>::Type>;
86	/*--------------------------------------------------------------------------------------------------------------------*/
87	template <typename Op, typename M, typename Expr>
88	constexpr auto FlattenOp(Op op, M map, Expr expr);
89	
90	template <typename Operand, typename M, typename Expr>
91	constexpr auto FlattenOperand(Operand operand, M map, Expr expr)
92	{
93	    auto [mapAfterOperand, localVarForOperand] = CreateLocalVar<Operand, Size_v<M> + 1>(map);
94	    constexpr bool needFlattenOperand = !IsParam_v<Operand> && !FindLocalVarIndex<M, Operand>;
95	    if constexpr (needFlattenOperand) {
96	        auto [mapAfterFlattenOperand, exprAfterFlattenOperand] = FlattenOp(operand, mapAfterOperand, expr);
97	        return std::tuple(localVarForOperand, mapAfterFlattenOperand, exprAfterFlattenOperand);
98	    } else {
99	        return std::tuple(localVarForOperand, mapAfterOperand, expr);
100	    }
101	}
102	
103	template <typename Op, typename M, typename Expr>
104	constexpr auto FlattenUnaryOp(Op op, M map, Expr expr)
105	{
106	    using Operand = typename Op::DataType;
107	    auto [localVar, mapAfterFlattenOperand, exprAfterFlattenOperand] = FlattenOperand(Operand{}, map, expr);
108	
109	    using NewAssign = MakeAssignOp<LocalVar<Size_v<M>, float, ParaConst>, Op, decltype(localVar)>;
110	    using FinalExpr = Append_t<decltype(exprAfterFlattenOperand), NewAssign>;
111	    return std::make_pair(mapAfterFlattenOperand, FinalExpr{});
112	}
113	
114	template <typename Op, typename M, typename Expr>
115	constexpr auto FlattenBinaryOp(Op op, M map, Expr expr)
116	{
117	    using LhsOperand = typename Op::LhsType;
118	    using RhsOperand = typename Op::RhsType;
119	    auto [localVarForLhs, mapAfterFlattenLhsOperand, exprAfterFlattenLhsOperand] =
120	        FlattenOperand(LhsOperand{}, map, expr);
121	    auto [localVarForRhs, mapAfterFlattenRhsOperand, exprAfterFlattenRhsOperand] =
122	        FlattenOperand(RhsOperand{}, mapAfterFlattenLhsOperand, exprAfterFlattenLhsOperand);
123	
124	    using NewAssign =
125	        MakeAssignOp<LocalVar<Size_v<M>, float, ParaConst>, Op, decltype(localVarForLhs), decltype(localVarForRhs)>;
126	    using FinalExpr = Append_t<decltype(exprAfterFlattenRhsOperand), NewAssign>;
127	    return std::make_pair(mapAfterFlattenRhsOperand, FinalExpr{});
128	}
129	
130	template <typename Op, typename M, typename Expr>
131	constexpr auto FlattenOp(Op op, M map, Expr expr)
132	{
133	    static_assert(IsUnaryOp_v<Op> || IsBinaryOp_v<Op>, "Op must be either UnaryOp or BinaryOp.");
134	
135	    if constexpr (IsUnaryOp_v<Op>) {
136	        return FlattenUnaryOp(op, map, expr);
137	    } else {
138	        return FlattenBinaryOp(op, map, expr);
139	    }
140	}
141	/*--------------------------------------------------------------------------------------------------------------------*/
142	template <typename Lhs, typename Rhs, typename M, typename Expr>
143	constexpr auto FlattenOpAssign(OpAssign<Lhs, Rhs>, M map, Expr expr)
144	{
145	    if constexpr (IsParam_v<Rhs>) {
146	        using FinalExpr = Append_t<Expr, OpAssign<Lhs, Rhs>>;
147	        return std::make_pair(map, FinalExpr{});
148	    } else if constexpr (IsUnaryOp_v<Rhs>) {
149	        using Operand = typename Rhs::DataType;
150	        auto [localVar, mapAfterFlattenOperand, exprAfterFlattenOperand] = FlattenOperand(Operand{}, map, expr);
151	
152	        using NewAssign = MakeAssignOp<Lhs, Rhs, decltype(localVar)>;
153	        using FinalExpr = Append_t<decltype(exprAfterFlattenOperand), NewAssign>;
154	        return std::make_pair(mapAfterFlattenOperand, FinalExpr{});
155	    } else if constexpr (IsBinaryOp_v<Rhs>) {
156	        using LhsOperand = typename Rhs::LhsType;
157	        using RhsOperand = typename Rhs::RhsType;
158	        auto [localVarForLhs, mapAfterFlattenLhsOperand, exprAfterFlattenLhsOperand] =
159	            FlattenOperand(LhsOperand{}, map, expr);
160	        auto [localVarForRhs, mapAfterFlattenRhsOperand, exprAfterFlattenRhsOperand] =
161	            FlattenOperand(RhsOperand{}, mapAfterFlattenLhsOperand, exprAfterFlattenLhsOperand);
162	
163	        using NewAssign = MakeAssignOp<Lhs, Rhs, decltype(localVarForLhs), decltype(localVarForRhs)>;
164	        using FinalExpr = Append_t<decltype(exprAfterFlattenRhsOperand), NewAssign>;
165	        return std::make_pair(mapAfterFlattenRhsOperand, FinalExpr{});
166	    } else {
167	        static_assert(true, "OpAssign's Right only support Param/UnaryOp/BinaryOp");
168	    }
169	}
