51	            startPos + Find_v<CheckForAssign<LocalVarType>::template Type, Drop_t<ExprList, startPos>>;
52	        using Type = TypeList<
53	            std::integral_constant<std::size_t, startPos>, std::integral_constant<std::size_t, writePos>,
