58	template <typename Index, typename Data>
59	struct IndexedData {
60	    using IndexType = Index;
61	    using DataType = Data;
62	
63	    IndexedData() = default;
64	    constexpr explicit IndexedData(Index)
65	    {}
66	    template <typename T>
67	    constexpr IndexedData(Index, T&& value) : data(std::forward<T>(value))
68	    {}
69	
70	    Data data;
71	};
