82	struct RedundantCastFinder {
83	    template <typename T, typename Result>
84	    constexpr auto operator()(T, Result) const
85	    {
86	        using Expr = typename T::Type;
87	        using NextIndex = std::integral_constant<std::size_t, typename Result::IndexType{} + 1>;
88	        using Data = typename Result::DataType;
89	        // 条件1：当前操作是赋值（OpAssign）
90	        if constexpr (Atvoss::Util::IsSpecializationOf_v<OpAssign, Expr>) {
91	            using TargetType = typename Expr::LhsType;
92	            using SourceType = typename Expr::RhsType;
93	            // 条件2：右值是类型转换（OpCast）
94	            if constexpr (IsOpCast_v<SourceType>) {
95	                using CastSourceType = typename SourceType::DataType;
96	                // 条件3：被转换的源数据是 局部变量或输入参数
97	                // 条件4：转换前后类型相同
98	                if constexpr (!IsLocalVar_v<CastSourceType> && !IsParam_v<CastSourceType>) {
99	                    return IndexedData<NextIndex, Data>{};
100	                } else if constexpr (std::is_same_v<typename CastSourceType::Type, typename TargetType::Type>) {
101	                    // TypeList<当前索引（冗余节点位置）, 被赋值的局部变量（TargetType）,
102	                    // 直接使用的源变量（CastSourceType）>
103	                    return IndexedData{
104	                        NextIndex{}, Atvoss::Util::Append_t<
105	                                         Data, TypeList<typename Result::IndexType, TargetType, CastSourceType>>{}};
106	                } else {
107	                    return IndexedData<NextIndex, Data>{};
108	                }
109	            } else {
110	                return IndexedData<NextIndex, Data>{};
111	            }
112	        } else {
113	            return IndexedData<NextIndex, Data>{};
114	        }
115	    }
116	};
