121	template <std::size_t I, std::size_t J, typename... Rest>
122	struct IsDeleted<I, TypeList<std::integral_constant<std::size_t, J>, Rest...>> {
123	    static constexpr bool value = (I == J) || IsDeleted<I, TypeList<Rest...>>::value;
124	};
