137	struct ExtractDeleteIndices<TypeList<TypeList<Index, A, B>, Tail...>> {
138	    static_assert(
139	        std::is_same_v<Index, std::integral_constant<std::size_t, Index::value>>,
140	        "First element must be std::integral_constant<std::size_t, ...>");
141	
