151	template <typename L, typename R, typename OldSym, typename NewSym>
152	struct ReplaceSymbol<OpAssign<L, R>, OldSym, NewSym> {
153	    using Type =
154	        OpAssign<typename ReplaceSymbol<L, OldSym, NewSym>::Type, typename ReplaceSymbol<R, OldSym, NewSym>::Type>;
155	};
