162	template <std::size_t I, typename Node, typename RangeList>
163	struct ApplyReplacements;
164	
165	template <std::size_t I, typename Node>
166	struct ApplyReplacements<I, Node, TypeList<>> {
167	    using Type = Node;
168	};
169	
170	template <
171	    std::size_t I, typename Node, std::size_t Start, std::size_t End, typename OldSym, typename NewSym,
172	    typename... Rest>
173	struct ApplyReplacements<
174	    I, Node,
175	    TypeList<
176	        TypeList<std::integral_constant<std::size_t, Start>, std::integral_constant<std::size_t, End>, OldSym, NewSym>,
177	        Rest...>> {
178	    static constexpr bool in_range = (Start <= I && I < End);
179	
180	    using NodeAfterCurrent = std::conditional_t<in_range, typename ReplaceSymbol<Node, OldSym, NewSym>::Type, Node>;
181	
182	    using Type = typename ApplyReplacements<I, NodeAfterCurrent, TypeList<Rest...>>::Type;
183	};
