191	template <typename Lhs, auto Mode, typename Reg, typename Src>
192	struct UnwrapOrNot<Lhs, OpCast<Mode, Reg, Src>, true> {
193	    using Type = OpAssign<Lhs, OpCopy<Src>>;
194	};
