201	template <typename Lhs, typename Rhs>
202	struct TryUnwrapRedundantCastInAssign<OpAssign<Lhs, Rhs>> {
203	private:
204	    template <typename T>
205	    struct IsRedundantCast : std::false_type {};
206	
207	    // 对 OpCast 的部分特化
208	    template <auto Mode, typename Reg, typename Src>
209	    struct IsRedundantCast<OpCast<Mode, Reg, Src>> {
210	        static constexpr bool value =
211	            (IsLocalVar_v<Src> || IsParam_v<Src>) && std::is_same_v<typename Src::Type, typename Lhs::Type>;
212	    };
213	
214	    template <typename T>
215	    static constexpr bool is_redundant_cast_v = IsRedundantCast<T>::value;
216	
217	    static constexpr bool is_redundant = is_redundant_cast_v<Rhs>;
218	
219	public:
220	    using Type = typename UnwrapOrNot<Lhs, Rhs, is_redundant>::Type;
221	};
222	
223	template <typename ExprList, typename ReplaceRangeList, std::size_t I = 0, typename Acc = TypeList<>, typename = void>
224	struct BuildOptimizedList;
225	
226	template <typename ExprList, typename ReplaceRangeList, std::size_t I, typename Acc>
227	struct BuildOptimizedList<ExprList, ReplaceRangeList, I, Acc, std::enable_if_t<(I == Size_v<ExprList>)>> {
228	    using Type = Acc;
229	};
230	
231	template <typename ExprList, typename ReplaceRangeList, std::size_t I, typename Acc>
232	struct BuildOptimizedList<ExprList, ReplaceRangeList, I, Acc, std::enable_if_t<(I < Size_v<ExprList>)>> {
233	    using CurrentNode = Get_t<ExprList, I>;
234	
235	    // Step A: 先 unwrap 冗余 cast（如果适用）
236	    using UnwrappedNode = typename TryUnwrapRedundantCastInAssign<CurrentNode>::Type;
237	
238	    // Step B: 再应用符号替换（如 item1 → item0，在后续表达式中）
239	    using ProcessedNode = typename ApplyReplacements<I, UnwrappedNode, ReplaceRangeList>::Type;
240	
241	    using NewAcc = Append_t<Acc, ProcessedNode>;
242	    using Type = typename BuildOptimizedList<ExprList, ReplaceRangeList, I + 1, NewAcc>::Type;
243	};
244	
245	template <typename ExprList>
246	__host_aicore__ constexpr decltype(auto) RemoveRedundantCast()
247	{
248	    using ReplaceItemList = typename decltype(ForEach(
249	        ExprList{}, RedundantCastFinder{},
250	        IndexedData{std::integral_constant<std::size_t, 0>{}, TypeList<>{}}))::DataType;
251	
252	    if constexpr (IsEmpty_v<ReplaceItemList>) {
253	        return ExprList{};
254	    } else {
255	        using ReplaceRangeList = Map_t<SafeReplaceRange<ExprList>::template Mapper, ReplaceItemList>;
256	
257	        using OptimizedNodeList = typename BuildOptimizedList<ExprList, ReplaceRangeList>::Type;
258	
259	        return OptimizedNodeList{};
260	    }
261	}
262	
263	} // namespace Atvoss::Graph
